The EXACT slide 2 CSS to use (replace the existing block from '@keyframes robotAssemble' through the energy flow rule):

/* ===== SLIDE 2 : STUNNING ROBOT ANIMATION ===== */
@keyframes robotAssemble {
    0% { opacity: 0; transform: translateY(40px) scale(0.7); filter: blur(4px); }
    50% { opacity: 1; transform: translateY(-8px) scale(1.05); filter: blur(0); }
    100% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
}
@keyframes energyFlow {
    0% { filter: drop-shadow(0 0 2px #0891b2); opacity: 0.7; }
    50% { filter: drop-shadow(0 0 12px #7c3aed) drop-shadow(0 0 20px #0891b2); opacity: 1; }
    100% { filter: drop-shadow(0 0 2px #0891b2); opacity: 0.7; }
}
@keyframes jointActivate {
    0% { opacity: 0; transform: scale(0) rotate(-180deg); filter: drop-shadow(0 0 0 transparent); }
    60% { opacity: 1; transform: scale(1.4) rotate(20deg); filter: drop-shadow(0 0 15px #7c3aed); }
    80% { transform: scale(0.9) rotate(-5deg); filter: drop-shadow(0 0 8px #0891b2); }
    100% { opacity: 1; transform: scale(1) rotate(0deg); filter: drop-shadow(0 0 6px rgba(124,58,237,0.5)); }
}
@keyframes jointPulse {
    0%, 100% { filter: drop-shadow(0 0 4px #0891b2); transform: scale(1); }
    25% { filter: drop-shadow(3px 0 8px #7c3aed) drop-shadow(-3px 0 8px #0891b2); transform: scale(1.08); }
    50% { filter: drop-shadow(0 0 16px #db2777) drop-shadow(0 0 24px #7c3aed); transform: scale(1.12); }
    75% { filter: drop-shadow(-3px 0 8px #7c3aed) drop-shadow(3px 0 8px #0891b2); transform: scale(1.06); }
}
@keyframes cameraLensFocus {
    0%, 100% { filter: drop-shadow(0 0 4px #22d3ee); transform: scale(1); }
    20% { filter: drop-shadow(0 0 16px #22d3ee) drop-shadow(0 0 28px #06b6d4); transform: scale(1.15); }
    40% { filter: drop-shadow(0 0 8px #0891b2); transform: scale(0.92); }
    60% { filter: drop-shadow(0 0 20px #7c3aed) drop-shadow(0 0 32px #22d3ee); transform: scale(1.1); }
    80% { filter: drop-shadow(0 0 6px #0891b2); transform: scale(0.96); }
}
@keyframes fovBeamShoot {
    0% { opacity: 0; stroke-dashoffset: 260; }
    50% { opacity: 0.8; }
    100% { opacity: 0.6; stroke-dashoffset: 0; }
}
@keyframes robotBreath {
    0%, 100% { transform: translateY(0) scale(1); }
    50% { transform: translateY(-3px) scale(1.008); }
}

.slide.active#slide-2 .gc-robot {
    animation: robotBreath 4s ease-in-out 4s infinite;
}
.slide.active#slide-2 .gc-robot > *:nth-child(1) { opacity: 0; animation: robotAssemble 0.8s cubic-bezier(0.34,1.56,0.64,1) forwards 0.2s; }
.slide.active#slide-2 .gc-robot > *:nth-child(2) { opacity: 0; animation: robotAssemble 0.7s cubic-bezier(0.34,1.56,0.64,1) forwards 0.5s; }
.slide.active#slide-2 .gc-robot > *:nth-child(3) { opacity: 0; animation: jointActivate 0.9s cubic-bezier(0.34,1.56,0.64,1) forwards 0.8s, jointPulse 3s ease-in-out 2.5s infinite; }
.slide.active#slide-2 .gc-robot > *:nth-child(4) { opacity: 0; animation: robotAssemble 0.7s cubic-bezier(0.34,1.56,0.64,1) forwards 1.1s; }
.slide.active#slide-2 .gc-robot > *:nth-child(5) { opacity: 0; animation: jointActivate 0.9s cubic-bezier(0.34,1.56,0.64,1) forwards 1.4s, jointPulse 3s ease-in-out 3s infinite; }
.slide.active#slide-2 .gc-robot > *:nth-child(6) { opacity: 0; animation: robotAssemble 0.7s cubic-bezier(0.34,1.56,0.64,1) forwards 1.7s; }
.slide.active#slide-2 .gc-robot > *:nth-child(7) { opacity: 0; animation: jointActivate 0.9s cubic-bezier(0.34,1.56,0.64,1) forwards 2.0s, jointPulse 3s ease-in-out 3.5s infinite; }
.slide.active#slide-2 .gc-robot > *:nth-child(8) { opacity: 0; animation: robotAssemble 0.6s cubic-bezier(0.34,1.56,0.64,1) forwards 2.3s; }
.slide.active#slide-2 .gc-camera {
    opacity: 0;
    animation: jointActivate 1s cubic-bezier(0.34,1.56,0.64,1) forwards 2.5s, 
               cameraLensFocus 3s ease-in-out 4s infinite;
}
.slide.active#slide-2 .gc-fov-line {
    opacity: 0; stroke-dasharray: 260; stroke-dashoffset: 260;
    animation: fovBeamShoot 0.8s ease forwards 3.0s;
}
.slide.active#slide-2 .gc-guide-line {
    opacity: 0; stroke-dasharray: 240; stroke-dashoffset: 240;
    animation: fovBeamShoot 0.7s ease forwards 3.1s;
}
.slide.active#slide-2 .gc-loop-path {
    opacity: 0; stroke-dasharray: 520; stroke-dashoffset: 520;
    animation: drawPath 1.4s ease forwards 3.3s;
}
.slide.active#slide-2 .gc-cam-label { opacity: 0; animation: floatInUp 0.5s ease forwards 2.9s; }
.slide.active#slide-2 .gc-fov-label { opacity: 0; animation: floatInUp 0.5s ease forwards 3.2s; }
.slide.active#slide-2 .gc-target-label { opacity: 0; animation: floatInUp 0.5s ease forwards 3.5s; }
.slide.active#slide-2 .gc-target { opacity: 0; animation: robotAssemble 0.8s cubic-bezier(0.34,1.56,0.64,1) forwards 2.8s; }
.slide.active#slide-2 .gc-card {
    opacity: 0; animation: popGlow 0.6s cubic-bezier(0.34,1.56,0.64,1) forwards;
}
.slide.active#slide-2 .gc-card:nth-child(1) { animation-delay: 3.6s; }
.slide.active#slide-2 .gc-card:nth-child(2) { animation-delay: 3.9s; }
.slide.active#slide-2 .gc-card:nth-child(3) { animation-delay: 4.2s; }
.slide.active#slide-2 .gc-robot rect,
.slide.active#slide-2 .gc-robot line { animation: energyFlow 2.5s ease-in-out 3s infinite; }
